@pytest.mark.parametrize('mode', ['read','iter','manual'])
def test_adjacent_records(mode):
    stream=SyncChunks([b'one',b'two'])
    response=httpx.Response(200,stream=stream)
    if mode=='read': assert response.read()==b'onetwo'
    elif mode=='iter': assert b''.join(response.iter_bytes())==b'onetwo'
    else: response.close()
    assert response.is_closed and stream.closes==1
    response.close(); assert stream.closes==1

