@pytest.mark.parametrize('payload', [b'one',b'x'*100,b''])
def test_observed_records(payload):
    import io
    class Unknown:
        def __init__(self,body): self.stream=io.BytesIO(body)
        def read(self,size=-1): return self.stream.read(size)
    request=httpx.Request('POST','http://case.invalid/upload',data={'note':'keep'},files={'known':('known.txt',b'known'),'unknown':('unknown.bin',Unknown(payload))})
    body=request.read()
    assert request.headers.get('transfer-encoding')=='chunked'
    assert 'content-length' not in request.headers
    assert b'name="unknown"; filename="unknown.bin"' in body
    assert b'\r\n\r\n'+payload+b'\r\n' in body and b'known' in body and b'keep' in body

@pytest.mark.parametrize('value', [{'message':'café Ω','items':[True,None,3]},['one','two'],{'nested':{'amount':2.5}}])
def test_observed_records(value):
    observed=[]
    def handler(request):
        observed.append(request)
        return httpx.Response(200,json={'received':json.loads(request.content)})
    with httpx.Client(transport=httpx.MockTransport(handler),trust_env=False) as client:
        response=client.post('https://case.invalid/json',json=value)
    assert response.json()=={'received':value}
    assert observed[0].headers['content-type']=='application/json'
    assert int(observed[0].headers['content-length'])==len(observed[0].content)

